#!/usr/bin/env python3
"""Assertions over the Android runner generated by the pinned Flutter SDK."""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
manifest = root / 'app/android/app/src/main/AndroidManifest.xml'
gradle = root / 'app/android/app/build.gradle.kts'
if not manifest.is_file() or not gradle.is_file():
    raise SystemExit('Generated Android runner missing.')
manifest_text = manifest.read_text(encoding='utf-8')
gradle_text = gradle.read_text(encoding='utf-8')
properties_text = (root / 'app/android/gradle.properties').read_text(encoding='utf-8')
for cap in ('org.gradle.jvmargs=-Xmx2048m -XX:MaxMetaspaceSize=512m',
            'org.gradle.workers.max=2', 'org.gradle.parallel=false',
            'kotlin.daemon.jvmargs=-Xmx512m'):
    assert cap in properties_text
assert 'android.permission.INTERNET' in manifest_text
assert 'android.permission.ACCESS_NETWORK_STATE' in manifest_text
assert 'android.permission.POST_NOTIFICATIONS' in manifest_text
activity = (root / 'app/android/app/src/main/kotlin/com/s4daharu/virthelm/MainActivity.kt').read_text()
assert 'registerDefaultNetworkCallback' in activity
assert 'unregisterNetworkCallback' in activity
assert 'com.s4daharu.virthelm/device_network' in activity
assert 'com.s4daharu.virthelm/incident_notifications' in activity
assert 'NotificationChannel' in activity
assert 'Open VirtHelm to review current incidents.' in activity
assert 'BackgroundCheckBridge.register' in activity
assert 'setLockScreenPrivacy' in activity
assert 'IncidentNotificationPrivacy.visibility' in activity
assert 'Notification.VISIBILITY_PUBLIC' not in activity
assert 'com.s4daharu.virthelm/incident_navigation' in activity
assert 'onNewIntent' in activity
assert 'takePendingIncidentNavigation' in activity
assert 'IncidentNotificationNavigation.contentIntent(this)' in activity
assert 'IncidentNotificationDeliveryLedger.profileKey(profileId)' in activity
assert 'cooldownMinutes = cooldownMinutes' in activity
assert (root / 'app/android/app/src/main/res/drawable/virthelm_notification.xml').is_file()
assert 'android:allowBackup="false"' in manifest_text
assert 'android:usesCleartextTraffic="false"' in manifest_text
assert 'android:label="VirtHelm"' in manifest_text
assert 'minSdk = 26' in gradle_text
assert 'applicationId = "com.s4daharu.virthelm"' in gradle_text
assert 'implementation("androidx.work:work-runtime:2.12.0")' in gradle_text
assert 'signingConfig = signingConfigs.getByName("debug")' not in gradle_text
worker_template = root / 'scripts/android/BackgroundIncidentWorker.kt'
if worker_template.is_file():
    worker = root / 'app/android/app/src/main/kotlin/com/s4daharu/virthelm/BackgroundIncidentWorker.kt'
    assert worker.is_file()
    worker_text = worker.read_text(encoding='utf-8')
    assert 'PeriodicWorkRequest.Builder' in worker_text
    assert 'NetworkType.CONNECTED' in worker_text
    assert 'AndroidKeyStore' in worker_text
    assert 'Notification.VISIBILITY_SECRET' in worker_text
    assert 'Notification.VISIBILITY_PRIVATE' in worker_text
    assert 'IncidentNotificationPrivacy.visibility' in worker_text
    assert 'Notification.VISIBILITY_PUBLIC' not in worker_text
    assert 'ACTION_OPEN_INCIDENTS' in worker_text
    assert 'PendingIntent.FLAG_IMMUTABLE' in worker_text
    assert 'IncidentNotificationNavigation.contentIntent(context)' in worker_text
    assert 'internal object IncidentNotificationDeliveryLedger' in worker_text
    assert 'virthelm_incident_delivery_v1' in worker_text
    assert 'Context.MODE_PRIVATE' in worker_text
    assert 'synchronized(lock)' in worker_text
    assert 'IncidentNotificationDeliveryLedger.clearKey(context, key)' in worker_text
    assert 'cooldownMinutes = policy.cooldownMinutes' in worker_text
    assert 'failedTaskChecksEnabled' in worker_text
    assert 'MAX_BACKGROUND_TASK_NODES = 16' in worker_text
    assert 'value != "."' in worker_text and 'value != ".."' in worker_text
    assert '/tasks?limit=20&source=all' in worker_text
    assert 'task-incident-active:' in worker_text
    assert 'task-watermark:' in worker_text
    assert 'endTimeSeconds > previousWatermarkSeconds' in worker_text
    assert 'MAX_BACKGROUND_NODE_CPU_RULES = 32' in worker_text
    assert 'nodeCpuThresholdChecksEnabled' in worker_text
    assert 'nodeCpuThresholdRules' in worker_text
    assert 'node-cpu-threshold-state:' in worker_text
    assert 'evaluateNodeCpuThresholds' in worker_text
    assert 'IncidentNotificationDeliveryLedger.profileKey(ruleId)' in worker_text
    navigation_intent = worker_text.split('internal object IncidentNotificationNavigation', 1)[1].split('internal data class ScheduledPolicy', 1)[0]
    assert 'putExtra(' not in navigation_intent
    assert 'instanceFollowRedirects = false' in worker_text
    assert 'requestMethod = "GET"' in worker_text
    assert 'Open VirtHelm to review current incidents.' in worker_text
print('Generated Android runner hardening checks passed.')
